<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import {projectId,currentProject,session,can} from '@/core/session'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {formatTime} from '@/core/time'
import AsyncState from '@/ui/AsyncState.vue'
import CursorPager from '@/ui/CursorPager.vue'
import {campaignStatusLabel} from '../../../../../things-link-console/src/features/ota/campaign-model'
import {jobStatusLabel,jobFailureHint,transitionSummary} from '../../../../../things-link-console/src/features/ota/job-model'
import {otaCampaignTransport,prepareOtaCampaignControl,type OtaCampaignTransport,type OtaCampaign,type OtaCampaignExecution,type OtaCampaignAction,type OtaCampaignControlIntent,type OtaCampaignJob,type OtaCampaignJobDetail} from './ota-campaign-api'
const props=withDefaults(defineProps<{campaignId:string;transport?:OtaCampaignTransport}>(),{transport:()=>otaCampaignTransport})
const emit=defineEmits<{locked:[boolean];changed:[]}>()
const member=computed(()=>session.ready&&!session.transitioning&&!!projectId.value&&!!session.user?.accountId&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const denied=ref(false),readable=computed(()=>member.value&&!denied.value),writable=computed(()=>readable.value&&can('ota:deploy')&&currentProject.value?.status==='ACTIVE')
const campaign=shallowRef<OtaCampaign>(),execution=shallowRef<OtaCampaignExecution>(),loading=ref(false),error=ref(''),executionError=ref(''),notice=ref('')
const jobs=shallowRef<readonly OtaCampaignJob[]>([]),jobLoading=ref(false),jobError=ref(''),jobPage=ref(1),jobCursors=ref<(string|undefined)[]>([undefined]),nextCursor=ref<string|null>(null),hasMore=ref(false),jobDetail=shallowRef<OtaCampaignJobDetail>()
const action=ref<OtaCampaignAction>(),reason=ref(''),shown=ref(false),busy=ref(false),unknown=ref(false),checked=ref(false),intent=shallowRef<OtaCampaignControlIntent>(),ack=shallowRef<OtaCampaign|OtaCampaignExecution>()
const locked=computed(()=>busy.value||unknown.value)
let generation=0,jobSequence=0,alive=true,controller:AbortController|undefined,jobController:AbortController|undefined
const labels:Record<OtaCampaignAction,string>={schedule:'排程并冻结目标',start:'启动活动',pause:'暂停活动',resume:'恢复活动',cancel:'取消活动',advance:'放行下一批'}
function capture(){return{generation,project:projectId.value,account:session.user?.accountId,epoch:identityEpoch(),id:props.campaignId}}
function current(s:ReturnType<typeof capture>){return alive&&readable.value&&s.generation===generation&&s.project===projectId.value&&s.account===session.user?.accountId&&s.epoch===identityEpoch()&&s.id===props.campaignId}
function clear(){generation++;jobSequence++;controller?.abort();jobController?.abort();campaign.value=undefined;execution.value=undefined;jobs.value=[];jobDetail.value=undefined;loading.value=false;jobLoading.value=false;busy.value=false;unknown.value=false;intent.value=undefined;ack.value=undefined;checked.value=false;action.value=undefined;shown.value=false;reason.value='';error.value='';jobError.value='';executionError.value='';notice.value='';jobPage.value=1;jobCursors.value=[undefined];nextCursor.value=null;hasMore.value=false}
function deniedError(cause:unknown){if(cause instanceof ApiError&&[401,403,404].includes(cause.status)){clear();denied.value=true;error.value='当前项目或活动管理权限不可用';return true}return false}
async function load(){if(!readable.value||locked.value)return;const s=capture();controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;campaign.value=undefined;execution.value=undefined;error.value='';executionError.value='';try{const row=await props.transport.read(s.project,s.id,signal);if(!current(s)||signal.aborted)return;campaign.value=row;if(currentProject.value?.status==='ACTIVE'){try{const runtime=await props.transport.execution(s.project,s.id,signal);if(current(s)&&!signal.aborted)execution.value=runtime}catch(cause){if(current(s)&&!signal.aborted&&!deniedError(cause))executionError.value=errorMessage(cause)}}}catch(cause){if(current(s)&&!signal.aborted&&!(cause instanceof IdentityChanged)&&!deniedError(cause))error.value=errorMessage(cause)}finally{if(current(s))loading.value=false}if(current(s)&&campaign.value)void loadJobs(1)}
async function loadJobs(page:number){if(!readable.value||jobLoading.value||page<1||page>jobCursors.value.length||locked.value)return;const s=capture(),sequence=++jobSequence;jobController?.abort();jobController=new AbortController();const signal=jobController.signal;jobLoading.value=true;jobError.value='';jobs.value=[];jobDetail.value=undefined;try{const result=await props.transport.jobs(s.project,s.id,jobCursors.value[page-1],signal);if(!current(s)||signal.aborted||sequence!==jobSequence)return;jobPage.value=page;jobs.value=result.items;nextCursor.value=result.nextCursor;hasMore.value=result.hasMore;if(result.hasMore&&result.nextCursor)jobCursors.value[page]=result.nextCursor}catch(cause){if(current(s)&&!signal.aborted&&sequence===jobSequence&&!deniedError(cause))jobError.value=errorMessage(cause)}finally{if(current(s)&&sequence===jobSequence)jobLoading.value=false}}
async function showJob(id:string){if(locked.value||!jobs.value.some(row=>row.id===id))return;const s=capture(),sequence=++jobSequence;jobController?.abort();jobController=new AbortController();const signal=jobController.signal;jobLoading.value=true;jobError.value='';jobDetail.value=undefined;try{const detail=await props.transport.job(s.project,s.id,id,signal);if(current(s)&&!signal.aborted&&sequence===jobSequence)jobDetail.value=detail}catch(cause){if(current(s)&&!signal.aborted&&!deniedError(cause))jobError.value=errorMessage(cause)}finally{if(current(s)&&sequence===jobSequence)jobLoading.value=false}}
function available(kind:OtaCampaignAction){if(!writable.value||locked.value||loading.value||!campaign.value)return false;try{prepareOtaCampaignControl(projectId.value,campaign.value,execution.value,kind,'管理操作');return true}catch{return false}}
function open(kind:OtaCampaignAction){if(!available(kind))return;action.value=kind;reason.value='';shown.value=true;error.value='';notice.value=''}
function closeAction(){if(!busy.value)shown.value=false}
function acceptedStatus(value:OtaCampaign|OtaCampaignExecution,original:OtaCampaignControlIntent){const statuses:Record<OtaCampaignAction,string[]>={schedule:['SCHEDULED'],start:['RUNNING'],pause:['PAUSED'],resume:['RUNNING'],cancel:['CANCELLING','CANCELLED'],advance:['RUNNING','COMPLETED']};return value.id===original.campaign&&BigInt(value.stateVersion)>BigInt(original.expectedRevision)&&statuses[original.action].includes(value.status)&&(!('planSha256'in value)||value.planSha256===original.planDigest)}
async function submit(){
 const before=campaign.value,kind=action.value;if(!before||!kind||!shown.value||!writable.value||locked.value)return
 const s=capture();busy.value=true;error.value='';controller=new AbortController();const signal=controller.signal;let sent=false,accepted=false
 try{const original=prepareOtaCampaignControl(s.project,before,execution.value,kind,reason.value)
  if(['schedule','start','resume','advance'].includes(kind)){const firmware=await props.transport.firmware(s.project,before.firmwareId,signal);if(!current(s)||signal.aborted)return;if(firmware.projectId!==s.project||firmware.id!==before.firmwareId||firmware.status!=='READY')throw new Error('固件当前未就绪，不能排程或准入升级作业')}
  if(!current(s)||signal.aborted||!writable.value)return
  intent.value=original;unknown.value=true;checked.value=false;ack.value=undefined;sent=true
  const response=await props.transport.control(original,signal);accepted=true
  if(!current(s)||signal.aborted)return
  if(!acceptedStatus(response,original))throw new Error('状态回执与原CAS操作不符，请只读核对')
  ack.value=response
  const actual=await props.transport.read(s.project,s.id,signal);if(!current(s)||signal.aborted)return
  if(actual.planSha256!==original.planDigest||BigInt(actual.stateVersion)<BigInt(response.stateVersion))throw new Error('原活动回读与操作回执不同')
  campaign.value=actual;unknown.value=false;intent.value=undefined;shown.value=false;execution.value=undefined;notice.value=`${labels[kind]}已受理；当前持久状态为${campaignStatusLabel(actual.status)}，不代表设备已安装。`;emit('changed')
 }catch(cause){if(current(s)&&!signal.aborted&&!(cause instanceof IdentityChanged)){
  if(!sent||!accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&[400,401,403,404,413,422,429].includes(cause.status)){unknown.value=false;intent.value=undefined}
  if(!deniedError(cause))error.value=errorMessage(cause)
 }}finally{if(current(s))busy.value=false}
}
async function observe(){const original=intent.value;if(!original||!unknown.value||busy.value||!readable.value)return;const s=capture();busy.value=true;checked.value=true;error.value='';controller=new AbortController();const signal=controller.signal;try{const row=await props.transport.read(original.project,original.campaign,signal);if(!current(s)||signal.aborted)return;if(row.planSha256!==original.planDigest)throw new Error('原活动计划身份不一致');campaign.value=row;if(ack.value&&BigInt(row.stateVersion)>=BigInt(ack.value.stateVersion)){unknown.value=false;intent.value=undefined;shown.value=false;execution.value=undefined;notice.value='原操作回执已独立回读；当前状态不代表设备安装完成';emit('changed')}else notice.value='已读取当前活动状态；当前同值不能证明原请求键的历史结果，不会重发。'}catch(cause){if(current(s)&&!signal.aborted&&!deniedError(cause))error.value=errorMessage(cause)}finally{if(current(s))busy.value=false}}
function finish(){if(unknown.value&&checked.value&&!busy.value){unknown.value=false;intent.value=undefined;ack.value=undefined;shown.value=false;notice.value='已结束核对，原状态操作结果仍未确认；请刷新后再决定新操作'}}
watch([()=>projectId.value,()=>session.user?.accountId,()=>member.value,()=>can('ota:deploy'),()=>props.campaignId],()=>{clear();denied.value=false;if(member.value)void load()},{immediate:true,flush:'sync'})
watch(locked,value=>emit('locked',value),{flush:'sync'})
const stop=onIdentityChange(clear)
onScopeDispose(()=>{alive=false;clear();stop();emit('locked',false)})
</script>
<template><section class="campaign-detail"><header><el-button size="small" :disabled="!readable||locked" :loading="loading" @click="load">刷新活动详情</el-button></header><el-alert v-if="notice" :title="notice" type="info" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <AsyncState :forbidden="!readable" :loading="loading" :error="!campaign&&error?new Error(error):undefined" @retry="load"><template v-if="campaign"><el-descriptions :column="2" border><el-descriptions-item label="活动ID">{{campaign.id}}</el-descriptions-item><el-descriptions-item label="状态">{{campaignStatusLabel(campaign.status)}} · 修订 {{campaign.stateVersion}}</el-descriptions-item><el-descriptions-item label="固件ID">{{campaign.firmwareId}}</el-descriptions-item><el-descriptions-item label="最早启动">{{formatTime(campaign.plan.notBefore)}}</el-descriptions-item><el-descriptions-item label="计划目标">{{campaign.plan.deviceIds.length}} 台</el-descriptions-item><el-descriptions-item label="冻结目标 / 批次">{{campaign.targetCount}} / {{campaign.batchCount}}</el-descriptions-item><el-descriptions-item label="计划摘要" :span="2">{{campaign.planSha256}}</el-descriptions-item></el-descriptions>
 <div class="campaign-controls"><el-button v-for="kind in (['schedule','start','pause','resume','cancel','advance'] as const)" :key="kind" size="small" :type="kind==='cancel'?'danger':'default'" :disabled="!available(kind)" @click="open(kind)">{{labels[kind]}}</el-button></div><p class="help">暂停仅关闭新准入，不中断已受理刷写；取消等待已派发责任安全收束，不撤销已成功升级。</p><p v-if="currentProject?.status!=='ACTIVE'" class="help">归档项目可读取计划和作业，执行快照与状态控制不可用。</p><el-alert v-if="executionError" :title="`执行快照未能读取：${executionError}`" type="warning" :closable="false"/>
 <div v-if="execution" class="help"><p>执行状态：{{campaignStatusLabel(execution.status)}} · 待准入 {{execution.pendingCount}} · 已持久通知意图 {{execution.dispatchedCount}} · 跳过 {{execution.skippedCount}}</p><p v-if="execution.runtimeCancellation">取消仍待收束 {{execution.runtimeCancellation.unresolvedCount}} 个已派发责任；{{execution.runtimeCancellation.completedAt?'已记录安全完成时间':'尚未记录安全完成时间'}}。</p><p>批次成功 {{execution.batchProgress.succeededCount}} / {{execution.batchProgress.targetCount}}；等待人工放行：{{execution.batchProgress.awaitingManualApproval?'是':'否'}}。</p></div>
 <el-alert v-if="unknown" title="原状态操作结果尚未确认；原键和CAS已保留，不会重发。" type="warning" :closable="false"><el-button size="small" :disabled="busy" @click="observe">读取原活动当前状态</el-button><el-button size="small" :disabled="busy||!checked" @click="finish">已核对，结束本次操作</el-button></el-alert>
 <h3>设备作业</h3><p class="help">作业与时间线只读，以下状态来自平台持久事实，不能代替物理设备验收。</p><el-alert v-if="jobError" :title="jobError" type="error" :closable="false"/><el-table :data="jobs" v-loading="jobLoading" empty-text="当前活动尚无冻结作业"><el-table-column prop="deviceId" label="设备ID" min-width="230"/><el-table-column prop="batchNumber" label="批次" width="70"/><el-table-column label="作业状态"><template #default="{row}">{{jobStatusLabel(row.status)}}</template></el-table-column><el-table-column label="失败原因"><template #default="{row}">{{row.failureCode||'—'}}</template></el-table-column><el-table-column width="90"><template #default="{row}"><el-button link type="primary" :disabled="locked||jobLoading" @click="showJob(row.id)">作业详情</el-button></template></el-table-column></el-table><CursorPager :page="jobPage" :limit="100" :has-next="hasMore" :loading="jobLoading||locked" :show-sizes="false" :show-pages="false" @update:page="loadJobs"/>
 </template></AsyncState><el-drawer :model-value="!!jobDetail" title="OTA作业结果" size="min(700px,95vw)" append-to-body @close="jobDetail=undefined"><template v-if="jobDetail"><p>{{jobDetail.id}} · {{jobStatusLabel(jobDetail.status)}} · 修订 {{jobDetail.stateVersion}}</p><p>{{jobFailureHint(jobDetail.failureCode)}}</p><p>以下为当前返回的 {{jobDetail.transitions.length}} 条持久转移。</p><ol><li v-for="row in jobDetail.transitions" :key="row.toRevision">{{formatTime(row.occurredAt)}} · {{transitionSummary(row)}} · {{row.reason||'—'}}</li></ol></template></el-drawer>
 <el-dialog :model-value="shown" :title="action?labels[action]:''" width="min(500px,95vw)" :close-on-click-modal="false" :show-close="!busy" @update:model-value="!$event&&closeAction()"><p v-if="action==='schedule'">确定按原计划冻结全部目标与批次？排程会建立设备作业占位。</p><p v-else-if="action==='start'||action==='resume'||action==='advance'">确定准入后续升级作业？平台可能向真实设备发送升级通知。请确认目标与发布固件。</p><p v-else>此操作按当前修订提交；不会撤销已经完成的设备升级。</p><el-input v-if="action&&!['schedule','start'].includes(action)" v-model="reason" aria-label="OTA活动操作原因" :disabled="busy||unknown" maxlength="256" placeholder="填写操作原因"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><p v-if="unknown">请关闭确认窗口后只读核对原活动，不要重复提交。</p><template #footer><el-button :disabled="busy" @click="closeAction">取消</el-button><el-button type="primary" :disabled="busy||unknown||!writable" :loading="busy" @click="submit">确认操作</el-button></template></el-dialog>
</section></template>
<style scoped>.campaign-controls{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.campaign-controls .el-button+.el-button{margin-left:0}.help{font-size:12px;line-height:1.7;color:var(--tl-muted)}.campaign-detail header{margin-bottom:14px}.campaign-detail .el-alert{margin:12px 0}.campaign-detail :deep(.el-descriptions__content){overflow-wrap:anywhere}</style>
